// STS2 enchantment ids (T4 run layer), generated by hand from the decompiled models
// (MegaCrit.Sts2.Core.Models.Enchantments). Only SOWN and PERFECT_FIT have combat
// behaviour wired; the rest are recognised ids whose effects are a recorded gap.

#ifndef STS2_ENCHANTMENT_H
#define STS2_ENCHANTMENT_H

#include <cstdint>

namespace sts2 {

enum class EnchantmentId : std::uint8_t {
    NONE = 0,
    ADROIT,
    CLONE,
    CORRUPTED,
    GLAM,
    GOOPY,
    IMBUED,
    INKY,
    INSTINCT,
    MOMENTUM,
    NIMBLE,
    PERFECT_FIT,
    ROYALLY_APPROVED,
    SHARP,
    SLITHER,
    SLUMBERING_ESSENCE,
    SOULS_POWER,
    SOWN,
    SPIRAL,
    STEADY,
    SWIFT,
    TEZCATARAS_EMBER,
    VIGOROUS,
    COUNT
};

inline const char* sts2EnchantmentName(EnchantmentId id) {
    switch (id) {
        case EnchantmentId::ADROIT: return "ADROIT";
        case EnchantmentId::CLONE: return "CLONE";
        case EnchantmentId::CORRUPTED: return "CORRUPTED";
        case EnchantmentId::GLAM: return "GLAM";
        case EnchantmentId::GOOPY: return "GOOPY";
        case EnchantmentId::IMBUED: return "IMBUED";
        case EnchantmentId::INKY: return "INKY";
        case EnchantmentId::INSTINCT: return "INSTINCT";
        case EnchantmentId::MOMENTUM: return "MOMENTUM";
        case EnchantmentId::NIMBLE: return "NIMBLE";
        case EnchantmentId::PERFECT_FIT: return "PERFECT_FIT";
        case EnchantmentId::ROYALLY_APPROVED: return "ROYALLY_APPROVED";
        case EnchantmentId::SHARP: return "SHARP";
        case EnchantmentId::SLITHER: return "SLITHER";
        case EnchantmentId::SLUMBERING_ESSENCE: return "SLUMBERING_ESSENCE";
        case EnchantmentId::SOULS_POWER: return "SOULS_POWER";
        case EnchantmentId::SOWN: return "SOWN";
        case EnchantmentId::SPIRAL: return "SPIRAL";
        case EnchantmentId::STEADY: return "STEADY";
        case EnchantmentId::SWIFT: return "SWIFT";
        case EnchantmentId::TEZCATARAS_EMBER: return "TEZCATARAS_EMBER";
        case EnchantmentId::VIGOROUS: return "VIGOROUS";
        default: return "NONE";
    }
}

// Sown (energy on first play), PerfectFit (top of pile after a reshuffle), Sharp
// (+damage on attack cards), Nimble (+block on cards that gain block) and Swift
// (draw on first play) are wired.
inline bool sts2EnchantmentImplemented(EnchantmentId id) {
    return id == EnchantmentId::SOWN || id == EnchantmentId::PERFECT_FIT
        || id == EnchantmentId::SHARP || id == EnchantmentId::NIMBLE
        || id == EnchantmentId::SWIFT || id == EnchantmentId::STEADY
        || id == EnchantmentId::SLITHER || id == EnchantmentId::SPIRAL
        || id == EnchantmentId::VIGOROUS || id == EnchantmentId::CORRUPTED
        || id == EnchantmentId::SOULS_POWER;
}

} // namespace sts2

#endif // STS2_ENCHANTMENT_H
